/// The tensor inventory of one layer of the authored forward, as `gen_qwen38_lg` declares it — recomputed
/// here from the config alone: `(q8_0 matrix elems, f32 tensor elems)` in declaration order.
fn layer_elems(c: &Qwen38Cfg, l: usize) -> (Vec<usize>, Vec<usize>) {
    let (d, dff, taps) = (c.d, c.dff, c.conv_taps);
    let (qk, vw, aq, akv, hd) = (c.gdn_qk(), c.gdn_v(), c.aq(), c.akv(), c.hd);
    let (nv, ghd) = (c.gdn_v_heads, c.gdn_head_dim);
    let (mut q8, mut f32s) = (Vec::new(), vec![d]);
    if c.is_attn(l) {
        q8.extend([d * aq, d * aq, d * akv, d * akv]);
        f32s.extend([hd, hd]);
        q8.push(aq * d);
    } else {
        q8.extend([d * qk, d * qk, d * vw, d * vw, d * nv, d * nv]);
        f32s.extend([taps * qk, taps * qk, taps * vw, nv, nv, ghd]);
        q8.push(vw * d);
    }
    f32s.push(d);
    q8.extend([d * dff, d * dff, dff * d]);
    (q8, f32s)
}

#[test]
fn the_qwen38_fit_is_derived_not_typed() {
    let c = real();
    let facts = sn50();
    let tp = rack(&facts);
    let ctx = c.ctx_len;
    let v = fresh_qwen(&facts, tp, ctx);
    let w = &v["model"]["weights"];

    let (d, dff, taps, vocab) = (c.d, c.dff, c.conv_taps, c.vocab);
    let (qk, vw, aq, akv, hd) = (c.gdn_qk(), c.gdn_v(), c.aq(), c.akv(), c.hd);
    let (h, nk, nv, ghd) = (c.h, c.gdn_k_heads, c.gdn_v_heads, c.gdn_head_dim);
    let q8 = |elems: usize| elems + elems.div_ceil(32) * 2;
    assert_eq!(
        q8_0_bytes(32),
        34,
        "one Q8_0 block: 32 int8 quants + one f16 scale"
    );
    assert_eq!(q8_0_bytes(64), q8(64));

    let (mut q8_bytes, mut f32_bytes, mut params, mut q8_count, mut f32_count) =
        (0usize, 0usize, 0usize, 0usize, 0usize);
    let mut per_layer_bytes_bf16 = Vec::new();
    let mut per_layer_macs = Vec::new();
    for l in 0..c.layers {
        let (q8s, f32s) = layer_elems(&c, l);
        let layer_params: usize = q8s.iter().chain(&f32s).sum();
        q8_bytes += q8s.iter().map(|&e| q8(e)).sum::<usize>();
        f32_bytes += f32s.iter().sum::<usize>() * F32_BYTES;
        params += layer_params;
        q8_count += q8s.len();
        f32_count += f32s.len();
        per_layer_bytes_bf16.push(layer_params * BF16_BYTES);
        let ffn = 2 * d * dff + dff * d;
        let (weight_macs, attention_macs, gdn_macs, conv_macs) = if c.is_attn(l) {
            (
                2 * d * aq + 2 * d * akv + aq * d + ffn,
                2 * h * hd * ctx,
                0,
                0,
            )
        } else {
            (
                2 * d * qk + 2 * d * vw + vw * d + 2 * d * nv + ffn,
                0,
                4 * nv * ghd * ghd,
                taps * (2 * qk + vw),
            )
        };
        per_layer_macs.push((
            weight_macs,
            attention_macs,
            gdn_macs,
            conv_macs,
            weight_macs + attention_macs + gdn_macs + conv_macs,
        ));
    }
    // The final norm, the untied LM head, and the embedding table the decode step gathers from.
    f32_bytes += d * F32_BYTES;
    f32_count += 1;
    params += d;
    q8_bytes += q8(d * vocab) + q8(vocab * d);
    q8_count += 2;
    params += 2 * d * vocab;

    assert_eq!(
        u(&w["q8_0_bytes"]),
        q8_bytes as u64,
        "Σ Q8_0 matrices: elems + elems/32 × 2 (f16 scales)"
    );
    assert_eq!(u(&w["f32_bytes"]), f32_bytes as u64, "Σ f32 tensors × 4");
    assert_eq!(u(&w["gguf_bytes"]), (q8_bytes + f32_bytes) as u64);
    assert_eq!(u(&w["params"]), params as u64);
    assert_eq!(
        u(&w["bf16_bytes"]),
        (params * BF16_BYTES) as u64,
        "the deployment dtype"
    );
    assert_eq!(u(&w["q8_0_tensors"]), q8_count as u64);
    assert_eq!(u(&w["f32_tensors"]), f32_count as u64);
    assert_eq!(u(&w["embedding"]["bytes"]), q8(vocab * d) as u64);

    let rows = v["per_layer"].as_array().expect("per_layer rows");
    assert_eq!(rows.len(), c.layers);
    for (l, row) in rows.iter().enumerate() {
        let (wm, am, gm, cm, total) = per_layer_macs[l];
        assert_eq!(row["layer"], l as u64);
        assert_eq!(row["kind"], if c.is_attn(l) { "attention" } else { "gdn" });
        assert_eq!(
            u(&row["weight_macs"]),
            wm as u64,
            "layer {l}: one MAC per weight element at batch 1"
        );
        assert_eq!(
            u(&row["attention_macs_at_ctx"]),
            am as u64,
            "layer {l}: scores and the weighted V-sum over ctx positions, every head"
        );
        assert_eq!(
            u(&row["gdn_recurrence_macs"]),
            gm as u64,
            "layer {l}: four ghd² passes over every v-head's ghd×ghd memory"
        );
        assert_eq!(
            u(&row["conv_macs"]),
            cm as u64,
            "layer {l}: taps × the q|k|v channels"
        );
        assert_eq!(u(&row["macs"]), total as u64);
        assert_eq!(u(&row["weight_bytes_bf16"]), per_layer_bytes_bf16[l] as u64);
        let ai = row["arithmetic_intensity_macs_per_byte"]
            .as_f64()
            .expect("a ratio");
        assert!(
            (ai - total as f64 / per_layer_bytes_bf16[l] as f64).abs() < 1e-9,
            "layer {l}: intensity = macs / weight bytes"
        );
    }

    let r = &v["residency"];
    assert_eq!(
        u(&r["kv_cache_bytes_per_token"]),
        (2 * akv * BF16_BYTES * c.attn_layers()) as u64,
        "K and V, bf16, every attention layer"
    );
    assert_eq!(
        u(&r["gdn_state_bytes"]),
        (vw * ghd * F32_BYTES * (c.layers - c.attn_layers())) as u64,
        "`St{{l}}` is vw × ghd f32 per GDN layer"
    );
    assert_eq!(
        u(&r["conv_state_bytes"]),
        (taps * (2 * qk + vw) * F32_BYTES * (c.layers - c.attn_layers())) as u64,
        "three conv rings (q, k, v) of `taps` rows per GDN layer"
    );
    let kv_at_ctx = &v["tensor_parallel"]["kv_cache_at_ctx"];
    assert_eq!(
        u(&kv_at_ctx["bytes"]),
        (2 * akv * BF16_BYTES * c.attn_layers() * ctx) as u64
    );
    let shards = tp.min(c.kv);
    assert_eq!(
        u(&kv_at_ctx["kv_shards"]),
        shards as u64,
        "the KV cache shards over kv heads, never wider"
    );
    assert_eq!(
        u(&kv_at_ctx["per_chip_bytes"]),
        (2 * akv * BF16_BYTES * c.attn_layers() * ctx / shards) as u64
    );
    assert_eq!(nk, c.gdn_k_heads);
}

#[test]
fn the_tensor_inventory_is_the_authored_programs_declarations() {
    let c = real();
    let facts = sn50();
    let v = fresh_qwen(&facts, rack(&facts), c.ctx_len);
    let (source, f32w, q8w) = gen_qwen38_lg(&c, "w");
    // Every `Let V be a R by C tensor of Real.` line, independently of the fit's own reader.
    let mut declared: BTreeMap<String, (usize, usize)> = BTreeMap::new();
    for line in source.lines() {
        let Some(rest) = line.strip_prefix("Let ") else {
            continue;
        };
        let Some((name, shape)) = rest.split_once(" be a ") else {
            continue;
        };
        let Some(shape) = shape.strip_suffix(" tensor of Real.") else {
            continue;
        };
        let (r, cc) = shape.split_once(" by ").expect("rows by cols");
        declared.insert(name.to_string(), (r.parse().unwrap(), cc.parse().unwrap()));
    }
    assert!(
        declared.len() > 10 * c.layers,
        "the forward declares a dozen or more tensors per layer, saw {}",
        declared.len()
    );
    let inventory = v["model"]["tensors"]
        .as_array()
        .expect("the fit lists its tensor inventory");
    let listed: BTreeMap<String, (usize, usize)> = inventory
        .iter()
        .map(|t| {
            (
                t["name"].as_str().unwrap().to_string(),
                (u(&t["rows"]) as usize, u(&t["cols"]) as usize),
            )
        })
        .collect();
    let mut expected = declared.clone();
    expected.insert("emb".into(), (c.vocab, c.d));
    assert_eq!(
        listed, expected,
        "the fit's inventory is exactly the authored declarations plus the embedding table"
    );
    for t in inventory {
        let name = t["name"].as_str().unwrap();
        let storage = t["storage"].as_str().unwrap();
        let class = t["class"].as_str().unwrap();
        if q8w.contains_key(name) || name == "emb" {
            assert_eq!(storage, "q8_0", "{name}");
            assert_eq!(class, "weight", "{name}");
        } else if f32w.contains_key(name) {
            assert_eq!(storage, "f32", "{name}");
            let is_state = name.starts_with("St") || name.starts_with("Cs");
            let is_rope = name == "RC" || name == "RS";
            assert_eq!(
                class,
                if is_state {
                    "state"
                } else if is_rope {
                    "rope_table"
                } else {
                    "weight"
                },
                "{name}"
            );
        } else {
            assert_eq!(
                name, "x",
                "the only undeclared-in-the-manifests tensor is the hidden state"
            );
            assert_eq!(class, "activation");
            assert_eq!(
                storage, "bf16",
                "activations are modeled in the deployment dtype"
            );
        }
    }
}

// ───────────────────────────── C ─────────────────────────────

#[test]
fn tensor_parallel_at_16_fits_the_hbm_and_at_1_does_not() {
    let facts = sn50();
    let c = real();
    let tp = rack(&facts);
    assert_eq!(
        tp, 16,
        "one SambaRack of SN50s is the tensor-parallel width the plan brings"
    );
    let at16 = fresh_qwen(&facts, tp, c.ctx_len);
    let t = &at16["tensor_parallel"];
    assert_eq!(t["dtype"], "bfloat16");
    assert_eq!(t["hbm_fit"], true, "bf16 weights / 16 + the KV cache at the full context + the recurrent state fit one RDU's HBM");
    assert!(u(&t["hbm_headroom_bytes"]) > 0);
    assert_eq!(
        u(&t["weights_per_chip_bytes"]),
        u(&t["sharded_weight_bytes_per_chip"]) + u(&t["replicated_weight_bytes"])
    );
    assert!(
        u(&t["max_ctx_in_hbm"]) >= c.ctx_len as u64,
        "the HBM holds at least the model's full context at TP=16"
    );

    let at1 = fresh_qwen(&facts, 1, c.ctx_len);
    let t1 = &at1["tensor_parallel"];
    assert_eq!(
        t1["hbm_fit"], false,
        "one RDU: ~54 GB of bf16 weights plus a full-context KV cache exceed 64 GiB"
    );
    assert!(
        t1["hbm_headroom_bytes"].as_i64().unwrap() < 0,
        "the shortfall is reported, signed"
    );
    assert!(u(&t1["max_ctx_in_hbm"]) < c.ctx_len as u64);
    assert_eq!(
        u(&t1["weights_per_chip_bytes"]),
        u(&at1["model"]["weights"]["bf16_bytes"]),
        "at TP=1 every weight is on the one chip"
    );

    let ladder = t["ladder"].as_array().expect("a TP ladder");
    let chips: Vec<u64> = ladder.iter().map(|r| u(&r["chips"])).collect();
    assert_eq!(
        chips,
        vec![1, facts.chips_per_node.value as u64, tp as u64],
        "the ladder is one RDU, one node, one rack"
    );
    assert_eq!(ladder[0]["hbm_fit"], false);
    assert_eq!(ladder[2]["hbm_fit"], true);
    assert!(u(&ladder[0]["weights_per_chip_bytes"]) > u(&ladder[1]["weights_per_chip_bytes"]));
    assert!(u(&ladder[1]["weights_per_chip_bytes"]) > u(&ladder[2]["weights_per_chip_bytes"]));
}

// ───────────────────────────── D ─────────────────────────────

#[test]
fn activations_per_token_fit_the_sram_and_the_gdn_state_tier_is_named() {
    let facts = sn50();
    let c = real();
    let tp = rack(&facts);
    let v = fresh_qwen(&facts, tp, c.ctx_len);
    let r = &v["residency"];
    let sram = facts.sram_bytes() as u64;
    assert_eq!(u(&r["sram_bytes"]), sram);
    let act = u(&r["activations_per_token_bytes"]);
    assert!(
        act > 0 && act <= sram,
        "activations per token ({act} B) fit the {sram} B SRAM"
    );
    assert_eq!(r["activations_fit_sram"], true);
    // A live set is bounded below by the widest single intermediate (a dff-wide bf16 row) and above by every
    // intermediate of the widest layer at once.
    let widest = (c.dff * BF16_BYTES) as u64;
    assert!(
        act >= widest,
        "the peak live set holds at least one dff-wide row: {act} < {widest}"
    );
    let all_of_a_layer =
        ((7 * c.d + 8 * c.gdn_qk() + 5 * c.gdn_v() + 4 * c.gdn_v_heads + 3 * c.dff)
            .max(7 * c.d + 7 * c.aq() + 4 * c.akv() + 3 * c.dff)
            * BF16_BYTES) as u64;
    assert!(act <= all_of_a_layer, "the peak live set never exceeds every intermediate of a layer at once: {act} > {all_of_a_layer}");
    assert!(matches!(
        r["activations_peak_layer_kind"].as_str(),
        Some("gdn") | Some("attention")
    ));
    // The LM head's moment — the logits row beside the normed hidden state — is the largest live set of the
    // whole step and is reported on its own, sharded vocab-parallel per chip.
    assert_eq!(
        u(&r["lm_head_live_set_bytes"]),
        ((c.vocab + c.d) * BF16_BYTES) as u64
    );
    assert_eq!(
        u(&r["lm_head_live_set_per_chip_bytes"]),
        ((c.vocab / tp + c.d) * BF16_BYTES) as u64
    );
    assert!(
        u(&r["lm_head_live_set_bytes"]) > act,
        "the logits row outweighs any layer's live set"
    );

    let tiers = &r["tiers"];
    assert_eq!(tiers["weights"], "hbm");
    assert_eq!(tiers["activations"], "sram");
    let gdn_per_chip = u(&r["gdn_state_bytes_per_chip"]);
    assert_eq!(
        gdn_per_chip,
        u(&r["gdn_state_bytes"]) / tp as u64,
        "the GDN memory shards over v-heads with TP"
    );
    let expected_tier = if gdn_per_chip + act <= sram {
        "sram"
    } else {
        "hbm"
    };
    assert_eq!(
        tiers["gdn_state"], expected_tier,
        "the GDN state's tier is derived from what is left of the SRAM after the activations"
    );
    assert_eq!(tiers["conv_state"], "sram");
    let kv_tier = &tiers["kv_cache"];
    let until = u(&kv_tier["sram_until_ctx"]);
    assert!(until > 0, "the KV cache lives in SRAM up to some context");
    assert_eq!(kv_tier["then"], "hbm");
    let kv_per_tok_chip = u(&r["kv_cache_bytes_per_token_per_chip"]);
    let free = sram - act - gdn_per_chip - u(&r["conv_state_bytes_per_chip"]);
    assert_eq!(
        until,
        free / kv_per_tok_chip,
        "the ceiling is the SRAM left after the recurrent working set, in tokens"
    );
    assert_eq!(
        r["sram_fit_per_chip"], true,
        "the recurrent working set (activations + GDN memory + conv rings) fits the SRAM"
    );
}

// ───────────────────────────── E ─────────────────────────────

/// A bare integer literal of three or more digits outside comments and doc lines — a number a reader cannot
/// trace to the config, the facts or the program. Years in citations and digits glued to identifiers are not.
fn typed_literals(source: &str) -> Vec<String> {
    let mut typed = Vec::new();
    for line in source.lines() {
        let l = line.trim();
        if l.starts_with("//") {
            continue;
        }
        let mut chars = l.char_indices().peekable();
        while let Some((i, c)) = chars.next() {
            if !c.is_ascii_digit() {
                continue;
            }
            let before = l[..i].chars().last();
            // Digits glued to an identifier, a decimal, or a format width (`{:016x}`) are not numbers off the page.
            if matches!(before, Some(b) if b.is_ascii_digit() || b == '.' || b.is_alphanumeric() || b == '_' || b == ':')
            {
                continue;
            }
            let rest: String = l[i..]
                .chars()
                .take_while(|c| c.is_ascii_digit() || *c == '_')
                .collect();
            let digits = rest.replace('_', "");
            let is_year = digits.len() == 4
                && digits
                    .parse::<u32>()
                    .map_or(false, |y| (1900..=2100).contains(&y));
            if digits.len() >= 3 && !is_year {
                typed.push(line.to_string());
                break;
            }
        }
    }
    typed
}

#[test]
fn the_generator_types_no_numbers_of_its_own() {
    for rel in FIT_SOURCES {
        let typed = typed_literals(&read(rel));
        assert!(
            typed.is_empty(),
            "{rel} types numbers a reader cannot audit:\n{}",
            typed.join("\n")
        );
    }
    // The scanner is not vacuous.
    assert_eq!(
        typed_literals("let x = 262144;\n// 262144 in a comment\nlet y = 32;\nlet z = 1 << 20;\n")
            .len(),
        1
    );
    assert!(typed_literals("let year = \"ISCA 2017\";").is_empty());
    assert!(
        typed_literals("format!(\"{:016x}\", digest)").is_empty(),
        "a format width is not a number"
    );
    assert_eq!(
        typed_literals("Foo { x: 262144 }").len(),
        1,
        "a struct field's literal is"
    );
}

// ───────────────────────────── I ─────────────────────────────

/// ── I. THE TENSOR-PARALLEL WIDTH IS ONE THE MODEL ADMITS. Qwen3.8-27B's 24 query heads, 4 KV heads and 16/48
/// Gated-DeltaNet heads split over 1, 2, 4 or 8 chips and no other width up to the rack's 16 — so it is served at
/// TP=8 (one SN50 node) with the rack's other node a data-parallel replica. A model with MiniMax-M2's 48 query heads
/// and 8 KV heads admits the whole rack.
#[test]
fn the_tensor_parallel_width_is_one_the_model_admits() {
    let c = real();
    let admitted: Vec<usize> = (1..=rack(&sn50()))
        .filter(|tp| qwen38_admits_tp(&c, *tp).is_ok())
        .collect();
    assert_eq!(
        admitted,
        vec![1, 2, 4, 8],
        "the widths Qwen3.8-27B splits over"
    );
    let why = qwen38_admits_tp(&c, 16)
        .expect_err("16 does not divide 24 query heads")
        .why;
    assert!(
        why.contains("24 query heads") && why.contains("16 chips"),
        "the refusal names the heads that do not split: `{why}`"
    );
    let kv = qwen38_admits_tp(
        &Qwen38Cfg {
            h: 12,
            kv: 4,
            gdn_k_heads: 6,
            gdn_v_heads: 6,
            dff: 6144,
            vocab: 6144,
            ..c.clone()
        },
        6,
    )
    .expect_err("6 neither splits nor evenly replicates 4 KV heads")
    .why;
    assert!(kv.contains("4 KV heads"), "`{kv}`");
    assert_eq!(
        qwen38_tensor_parallel(&c, &sn50()),
        8,
        "the widest width the model admits within the rack's 16"
    );
    let wide = Qwen38Cfg {
        h: 48,
        kv: 8,
        ..c.clone()
    };
    assert_eq!(
        qwen38_tensor_parallel(&wide, &sn50()),
        16,
        "48 query heads and 8 KV heads admit the whole rack"
    );
}

// ───────────────────────────── J ─────────────────────────────

/// ── J. THE SERVING PLAN IS READ OFF THE CHIPS AND THE MODEL, never typed: TP=8 by the heads, the rack's other node a
/// replica, and a replica's sequences exactly as many as each chip's HBM holds beside its weights.
#[test]
fn the_serving_plan_is_read_off_the_chips_and_the_model() {
    let (facts, c) = (sn50(), real());
    let ctx = 4096;
    let plan = qwen38_serving_plan(&c, &facts, ctx).expect("a serving plan at 4096 positions");
    assert_eq!(plan.tensor_parallel, qwen38_tensor_parallel(&c, &facts));
    assert_eq!(
        plan.tensor_parallel, 8,
        "the widest width Qwen3.8-27B's heads admit in the rack"
    );
    assert_eq!(
        plan.data_parallel,
        rack(&facts) / 8,
        "the rack's other node is a replica"
    );

    // The sequence count is the fit's own per-chip bytes, recomputed: HBM beside the weight slice over one sequence's
    // carried state at the context.
    let fit = fresh_qwen(&facts, plan.tensor_parallel, ctx);
    let t = &fit["tensor_parallel"];
    let seq = u(&t["state_bytes_per_chip"]) + u(&t["kv_cache_at_ctx"]["per_chip_bytes"]);
    let (hbm, weights) = (u(&t["hbm_bytes_per_chip"]), u(&t["weights_per_chip_bytes"]));
    assert_eq!(plan.sequence_bytes_per_chip as u64, seq);
    let n = plan.max_sequences_per_replica as u64;
    assert!(
        weights + n * seq <= hbm && weights + (n + 1) * seq > hbm,
        "the count is tight: {n} sequences fit, {} do not",
        n + 1
    );
    assert_eq!(
        plan.max_sequences,
        plan.max_sequences_per_replica * plan.data_parallel
    );

    // The context moves it: 64× the context is a KV cache that dominates, and far fewer sequences fit.
    let long = qwen38_serving_plan(&c, &facts, ctx * 64).expect("a plan at the long context");
    assert!(
        long.max_sequences_per_replica * 8 < plan.max_sequences_per_replica,
        "{} at {} positions vs {} at {ctx}",
        long.max_sequences_per_replica,
        ctx * 64,
        plan.max_sequences_per_replica
    );

    // Two-sided in the chip: more HBM holds more sequences; HBM that does not hold the weight slice is refused by name.
    let roomy = qwen38_serving_plan(
        &c,
        &facts
            .clone()
            .with_hbm_gib(Fact::modeled(128, "probe: a 128 GiB HBM")),
        ctx,
    )
    .expect("a plan on the roomier chip");
    assert!(roomy.max_sequences_per_replica > plan.max_sequences_per_replica * 2);
    let starved = qwen38_serving_plan(
        &c,
        &facts
            .clone()
            .with_hbm_gib(Fact::modeled(4, "probe: a 4 GiB HBM")),
        ctx,
    )
    .expect_err("4 GiB does not hold an eighth of the weights");
    assert!(
        starved.contains("do not hold its") && starved.contains("weights"),
        "{starved}"
    );

    // On-chip: the sequences whose per-step working set and recurrent state stay in SRAM.
    let r = &fit["residency"];
    let on_chip = u(&r["activations_per_token_bytes"])
        + u(&r["gdn_state_bytes_per_chip"])
        + u(&r["conv_state_bytes_per_chip"]);
    let k = plan.sequences_resident_in_sram as u64;
    assert!(
        k * on_chip <= plan.sram_bytes_per_chip as u64
            && (k + 1) * on_chip > plan.sram_bytes_per_chip as u64
    );

    let v = serde_json::to_value(&plan).unwrap();
    assert_eq!(v["provenance"], PROVENANCE_MODELED);
    assert_eq!(v["no_speed_claim"], true);
    for key in v.as_object().unwrap().keys() {
        assert!(!is_time_key(key), "`{key}` is a time-valued field");
    }
}

// ───────────────────────────── F ─────────────────────────────

#[test]
fn the_fit_is_two_sided_in_the_chip() {
    let c = real();
    let (sn40l, sn50) = (RduChipFacts::sn40l(), sn50());
    let tp = rack(&sn50);
    let a = fresh_qwen(&sn40l, tp, c.ctx_len);
    let b = fresh_qwen(&sn50, tp, c.ctx_len);
    assert_eq!(a["chip"]["part"], "SN40L");
    assert_eq!(b["chip"]["part"], "SN50");
    assert_eq!(u(&a["chip"]["sram_bytes"]["value"]), 520 << 20);
    assert_eq!(u(&b["chip"]["sram_bytes"]["value"]), 432 << 20);
    assert_eq!(u(&a["chip"]["peak_bf16_tflops"]["value"]), 638);
    assert_eq!(u(&b["chip"]["peak_bf16_tflops"]["value"]), 1600);
    assert_eq!(
        a["chip"]["peak_bf16_tflops"]["provenance"],
        PROVENANCE_PUBLISHED
    );
    assert!(
        u(&a["residency"]["tiers"]["kv_cache"]["sram_until_ctx"])
            > u(&b["residency"]["tiers"]["kv_cache"]["sram_until_ctx"]),
        "more SRAM holds more KV cache"
    );
    assert_eq!(
        a["model"]["weights"], b["model"]["weights"],
        "the model does not change with the chip"
    );
    assert_ne!(
        a["chip"]["modeled_fields"], b["chip"]["modeled_fields"],
        "the SN50's PCU/PMU counts are modeled; the SN40L's are published"
    );

    // An HBM number dropped in as data flips the verdict both ways, at both ends of the ladder.
    let rack_fits = fresh_qwen(&sn50, tp, c.ctx_len);
    assert_eq!(rack_fits["tensor_parallel"]["hbm_fit"], true);
    let rack_starved = fresh_qwen(
        &sn50
            .clone()
            .with_hbm_gib(Fact::modeled(4, "probe: a 4 GiB HBM")),
        tp,
        c.ctx_len,
    );
    assert_eq!(
        rack_starved["tensor_parallel"]["hbm_fit"], false,
        "4 GiB per chip cannot hold a sixteenth of the model plus a quarter of the KV cache"
    );
    assert_eq!(u(&rack_starved["chip"]["hbm_bytes"]["value"]), 4 << 30);
    assert_eq!(
        rack_starved["chip"]["hbm_bytes"]["provenance"],
        PROVENANCE_MODELED
    );
    let one_starved = fresh_qwen(&sn50, 1, c.ctx_len);
    assert_eq!(one_starved["tensor_parallel"]["hbm_fit"], false);
    let one_fits = fresh_qwen(
        &sn50
            .clone()
            .with_hbm_gib(Fact::modeled(128, "probe: a 128 GiB HBM")),
        1,
        c.ctx_len,
    );
    assert_eq!(
        one_fits["tensor_parallel"]["hbm_fit"], true,
        "128 GiB holds the whole bf16 model and its full-context KV cache on one chip"
    );

    let g40 = fresh_gemm(&sn40l);
    let g50 = fresh_gemm(&sn50);
    assert_eq!(
        g40["workload"]["macs"], g50["workload"]["macs"],
        "the same workload"
    );
    assert_ne!(g40["chip"], g50["chip"], "on a different chip");
    assert_eq!(g40["chip"]["target"], "sn40l-rdu");
    assert_eq!(g50["chip"]["target"], "sn50-rdu");
}

// ───────────────────────────── G ─────────────────────────────

/// A key that would carry a time, a rate of ours, or a speed. The vendor's published peak rates
/// (`*_tflops`, `link_gbps`, `tb_s_per_chip`) are allowed only under a `published` label with a citation.
fn is_time_key(key: &str) -> bool {
    if key == "no_speed_claim" {
        return false;
    }
    let k = key.to_ascii_lowercase();
    [
        "latency",
        "throughput",
        "speed",
        "duration",
        "elapsed",
        "wall",
        "time",
        "tokens_per",
        "tok_s",
        "per_sec",
        "seconds",
    ]
    .iter()
    .any(|w| k.contains(w))
        || k.ends_with("_ms")
        || k.ends_with("_us")
        || k.ends_with("_ns")
        || k.ends_with("_sec")
        || k.ends_with("_s")
}

fn is_rate_key(key: &str) -> bool {
    let k = key.to_ascii_lowercase();
    k.contains("tflops") || k.contains("gbps") || k.contains("tb_s")
}

/// Walk every numeric leaf: report `(path, nearest provenance label, has a citation)`, and every key.
fn audit(
    v: &Value,
    path: &mut Vec<String>,
    label: Option<(String, bool)>,
    leaves: &mut Vec<(String, Option<(String, bool)>)>,
    keys: &mut Vec<String>,
) {
    match v {
        Value::Number(_) => leaves.push((path.join("."), label)),
        Value::Object(m) => {
            let here = m.get("provenance").and_then(Value::as_str).map(|p| {
                (
                    p.to_string(),
                    m.get("cite")
                        .and_then(Value::as_str)
                        .map_or(false, |c| !c.trim().is_empty()),
                )
            });
            let label = here.or(label);
            for (k, child) in m {
                keys.push(format!("{}.{k}", path.join(".")));
                path.push(k.clone());
                audit(child, path, label.clone(), leaves, keys);
                path.pop();
            }
        }
        Value::Array(items) => {
            for (i, child) in items.iter().enumerate() {
                path.push(i.to_string());
                audit(child, path, label.clone(), leaves, keys);
                path.pop();
            }
        }
        _ => {}
    }
}

fn assert_labeled_and_timeless(name: &str, v: &Value) {
    assert_eq!(v["no_speed_claim"], true, "{name}: no_speed_claim");
    assert_eq!(
        v["provenance"], PROVENANCE_MODELED,
        "{name}: the artifact is modeled"
    );
    let (mut leaves, mut keys) = (Vec::new(), Vec::new());
    audit(v, &mut Vec::new(), None, &mut leaves, &mut keys);
    assert!(
        leaves.len() > 20,
        "{name}: the audit saw only {} numbers — it is not walking the artifact",
        leaves.len()
    );
    for (path, label) in &leaves {
        let (prov, cited) = label
            .as_ref()
            .unwrap_or_else(|| panic!("{name}: `{path}` is a number under no `provenance` label"));
        assert!(
            prov == PROVENANCE_MODELED || prov == PROVENANCE_PUBLISHED,
            "{name}: `{path}` is labeled `{prov}`, which is neither modeled nor published"
        );
        if prov == PROVENANCE_PUBLISHED {
            assert!(cited, "{name}: `{path}` is published without a citation");
        }
    }
    let n_published = leaves
        .iter()
        .filter(|(_, l)| l.as_ref().map_or(false, |(p, _)| p == PROVENANCE_PUBLISHED))
        .count();
    assert!(
        n_published > 0,
        "{name}: the chip's published numbers travel with their label"
    );
    for key in &keys {
        let last = key.rsplit('.').next().unwrap();
        assert!(
            !is_time_key(last),
            "{name}: `{key}` is a time-valued field — nothing here ran on the chip"
        );
    }
    for (path, label) in &leaves {
        let last = path
            .rsplit('.')
            .find(|s| s.parse::<usize>().is_err())
            .unwrap_or("");
        let under_rate = path.split('.').any(is_rate_key) || is_rate_key(last);
        if under_rate {
            assert_eq!(
                label.as_ref().map(|(p, _)| p.as_str()),
                Some(PROVENANCE_PUBLISHED),
                "{name}: `{path}` is a rate; only the vendor's published rates may appear, cited"
            );
        }
    }
}

#[test]
fn every_number_is_labeled_modeled_and_no_field_is_a_time() {
    let facts = sn50();
    let c = real();
    let tp = rack(&facts);
    assert_labeled_and_timeless("gemm fit (fresh)", &fresh_gemm(&facts));
    assert_labeled_and_timeless("qwen38 fit (fresh)", &fresh_qwen(&facts, tp, c.ctx_len));
    assert_labeled_and_timeless("vllm plan (fresh)", &fresh_plan(&facts, tp));
    assert_labeled_and_timeless("gemm fit (on disk)", &json(GEMM_FIT_PATH));
    assert_labeled_and_timeless("qwen38 fit (on disk)", &json(QWEN38_FIT_PATH));
    assert_labeled_and_timeless("vllm plan (on disk)", &json(VLLM_PLAN_PATH));
    // The audit has teeth.
    assert!(
        is_time_key("latency_ms")
            && is_time_key("tok_s")
            && is_time_key("throughput")
            && is_time_key("decode_time")
            && is_time_key("speedup")
    );
    assert!(
        !is_time_key("no_speed_claim"),
        "the honesty flag is the one key that may spell the word"
    );
    assert!(
        !is_time_key("bytes")
            && !is_time_key("pipeline_ii")
            && !is_time_key("forward_cycles")
            && !is_time_key("sram_until_ctx")
    );
    let bad = serde_json::json!({ "provenance": "modeled", "no_speed_claim": true, "x": vec![1u64; 60], "latency_ms": 1 });
    assert!(
        std::panic::catch_unwind(|| assert_labeled_and_timeless("probe", &bad)).is_err(),
        "a time key must fail the audit"
    );
    let unlabeled = serde_json::json!({ "provenance": "modeled", "no_speed_claim": true, "x": vec![1u64; 60], "chip": { "peak_bf16_tflops": 1600 } });
    assert!(
        std::panic::catch_unwind(|| assert_labeled_and_timeless("probe", &unlabeled)).is_err(),
        "a rate under a modeled label must fail the audit"
    );
}

