#[test]
fn the_vllm_plan_is_derived_from_the_fit() {
    let facts = sn50();
    let c = real();
    let tp = rack(&facts);
    let fit = fresh_qwen(&facts, tp, c.ctx_len);
    let plan = fresh_plan(&facts, tp);
    assert_eq!(plan["model"]["id"], QWEN38_MODEL_ID);
    assert_eq!(plan["model"]["hf_model_type"], "qwen3_5");
    assert_eq!(plan["model"]["inherits"], "qwen3_next");
    let serve = &plan["serve"];
    assert_eq!(serve["tensor_parallel_size"], tp as u64);
    assert_eq!(serve["dtype"], "bfloat16");
    assert_eq!(
        serve["max_model_len"], c.ctx_len as u64,
        "max-model-len is the model's context length"
    );
    let cmd = serve["command"].as_str().unwrap();
    assert!(
        cmd.starts_with("vllm serve ")
            && cmd.contains(QWEN38_MODEL_ID)
            && cmd.contains(&format!("--tensor-parallel-size {tp}"))
            && cmd.contains("--dtype bfloat16")
            && cmd.contains(&format!("--max-model-len {}", c.ctx_len)),
        "{cmd}"
    );

    let ops: Vec<&str> = plan["ops_the_backend_must_support"]
        .as_array()
        .unwrap()
        .iter()
        .map(|o| o["op"].as_str().unwrap())
        .collect();
    for needed in [
        "rmsnorm",
        "matmul",
        "rope",
        "gqa_attention",
        "sigmoid_gate",
        "causal_conv",
        "silu",
        "l2norm_per_head",
        "decay",
        "gated_delta",
        "swiglu",
        "argmax",
    ] {
        assert!(
            ops.contains(&needed),
            "the op list names `{needed}`: {ops:?}"
        );
    }
    let op = |name: &str| {
        plan["ops_the_backend_must_support"]
            .as_array()
            .unwrap()
            .iter()
            .find(|o| o["op"] == name)
            .unwrap()
            .clone()
    };
    let rope = op("rope");
    assert_eq!(rope["rotary_dims"], c.rope_dim as u64);
    assert_eq!(rope["head_dim"], c.hd as u64);
    assert_eq!(rope["theta"].as_f64(), Some(c.rope_theta));
    let attn = op("gqa_attention");
    assert_eq!(attn["heads"], c.h as u64);
    assert_eq!(attn["kv_heads"], c.kv as u64);
    assert_eq!(attn["head_dim"], c.hd as u64);
    let conv = op("causal_conv");
    assert_eq!(conv["taps"], c.conv_taps as u64);
    let gd = op("gated_delta");
    assert_eq!(gd["v_heads"], c.gdn_v_heads as u64);
    assert_eq!(gd["k_heads"], c.gdn_k_heads as u64);
    assert_eq!(gd["head_dim"], c.gdn_head_dim as u64);
    assert_eq!(gd["layers"], (c.layers - c.attn_layers()) as u64);
    assert_eq!(attn["layers"], c.attn_layers() as u64);

    let st = &plan["state_bytes_per_layer"];
    let r = &fit["residency"];
    assert_eq!(
        u(&st["attention_kv_per_token"]),
        u(&r["kv_cache_bytes_per_token"]) / c.attn_layers() as u64
    );
    assert_eq!(
        u(&st["gdn_memory"]),
        u(&r["gdn_state_bytes"]) / (c.layers - c.attn_layers()) as u64
    );
    assert_eq!(
        u(&st["conv_rings"]),
        u(&r["conv_state_bytes"]) / (c.layers - c.attn_layers()) as u64
    );

    let ff = &plan["from_fit"];
    assert_eq!(
        ff["weights_bf16_bytes"],
        fit["model"]["weights"]["bf16_bytes"]
    );
    assert_eq!(
        ff["weights_per_chip_bytes"],
        fit["tensor_parallel"]["weights_per_chip_bytes"]
    );
    assert_eq!(ff["hbm_fit"], fit["tensor_parallel"]["hbm_fit"]);
    assert_eq!(
        ff["kv_cache_at_ctx"],
        fit["tensor_parallel"]["kv_cache_at_ctx"]
    );
    assert_eq!(
        ff["max_ctx_in_hbm"],
        fit["tensor_parallel"]["max_ctx_in_hbm"]
    );
    assert!(
        plan["intake_question"]
            .as_str()
            .unwrap()
            .contains("qwen3_5"),
        "the first question of the day travels with the plan"
    );
    assert_eq!(plan["chip"]["part"], "SN50");
    assert_eq!(plan["chip"]["chips_per_rack"]["value"], tp as u64);
}

/// The II block moves with the descriptor: a deeper PCU pipeline (a number dropped in as data) lengthens
/// every stage's result cycles by the same amount, and the report says so — MODELED.
#[test]
fn the_ii_report_block_is_modeled_and_moves_with_the_descriptor() {
    let facts = sn50();
    let c = real();
    let tp = rack(&facts);
    let base = fresh_qwen(&facts, tp, c.ctx_len);
    let deeper = fresh_qwen(
        &facts
            .clone()
            .with_pcu_stages(Fact::modeled(7, "probe: one more PCU stage")),
        tp,
        c.ctx_len,
    );
    let ii = &base["ii_report"];
    assert_eq!(ii["provenance"], PROVENANCE_MODELED);
    assert_eq!(ii["chip"], "sn50");
    assert!(
        ii["program"].as_str().unwrap().starts_with("rmsnorm_1x"),
        "the II block is the tiny config's rmsnorm chain: {}",
        ii["program"]
    );
    let stages = ii["stages"].as_array().unwrap();
    let stages7 = deeper["ii_report"]["stages"].as_array().unwrap();
    assert!(
        stages.len() >= 4,
        "the rmsnorm chain is several compute stages"
    );
    assert_eq!(stages.len(), stages7.len());
    for (s6, s7) in stages.iter().zip(stages7) {
        assert_eq!(
            u(&s7["result_cycles"]),
            u(&s6["result_cycles"]) + 1,
            "{}: one more PCU stage is one more cycle to a result",
            s6["name"]
        );
        assert!(
            s6.get("latency").is_none() && s6["timing"].is_null(),
            "the II block spells cycles, never latency"
        );
    }
    assert_eq!(base["ii_report"]["unit_model"]["pcu_stages"]["value"], 6);
    assert_eq!(deeper["ii_report"]["unit_model"]["pcu_stages"]["value"], 7);
    let g = fresh_gemm(&facts);
    assert_eq!(
        g["ii_report"]["program"], g["program"]["name"],
        "the GEMM fit's II block is the GEMM's own"
    );
    assert_eq!(RduChip::Sn50.as_str(), "sn50");
    assert_eq!(SpatialTarget::sn50_rdu().name, "sn50-rdu");
}
